11	/**
12	 * Input to an operator.
13	 */
14	export interface InputBase {
15	  /** The schema of the data this input returns. */
16	  getSchema(): SourceSchema;
17	
18	  /**
19	   * Completely destroy the input. Destroying an input
20	   * causes it to call destroy on its upstreams, fully
21	   * cleaning up a pipeline.
22	   */
23	  destroy(): void;
24	}
25	
26	export interface Input extends InputBase {
27	  /** Tell the input where to send its output. */
28	  setOutput(output: Output): void;
29	
30	  /**
31	   * Fetch data. May modify the data in place.
32	   * Returns nodes sorted in order of `SourceSchema.compareRows`.
33	   *
34	   * The stream may contain 'yield' to yield control to the caller for purposes
35	   * of responsiveness.
36	   *
37	   * Contract:
38	   * - During fetch: If an input yields 'yield', 'yield' must be yielded to the
39	   * caller of fetch immediately.
40	   * - During push: If a fetch to an input consumed by the push logic yields
41	   * 'yield', it must be yielded to the caller of push immediately.
42	   */
43	  fetch(req: FetchRequest): Stream<Node | 'yield'>;
44	}
45	
46	export type FetchRequest = {
47	  readonly constraint?: Constraint | undefined;
48	  /** If supplied, `start.row` must have previously been output by fetch or push. */
49	  readonly start?: Start | undefined;
50	
51	  /** Whether to fetch in reverse order of the SourceSchema's sort. */
52	  readonly reverse?: boolean | undefined;
53	};
54	
55	export type Start = {
56	  readonly row: Row;
57	  readonly basis: 'at' | 'after';
58	};
59	
60	/**
61	 * An output for an operator. Typically another Operator but can also be
62	 * the code running the pipeline.
63	 */
64	export interface Output {
65	  /**
66	   * Push incremental changes to data previously received with fetch().
67	   * Consumers must apply all pushed changes or incremental result will
68	   * be incorrect.
69	   * Callers must maintain some invariants for correct operation:
70	   * - Only add rows which do not already exist (by deep equality).
71	   * - Only remove rows which do exist (by deep equality).
72	   * Implmentation can yield 'yield' to yield control to the caller for purposes
73	   * of responsiveness.
74	   * Yield contract:
75	   * - During a push: If a push call to an output yields 'yield', it must be
76	   * yielded to the caller of push immediately.
77	   */
78	  push(change: Change, pusher: InputBase): Stream<'yield'>;
79	}
80	
81	/**
82	 * An implementation of Output that throws if pushed to. It is used as the
83	 * initial value for for an operator's output before it is set.
84	 */
85	export const throwOutput: Output = {
86	  push(_change: Change): Stream<'yield'> {
87	    throw new Error('Output not set');
88	  },
89	};
90	
91	/**
92	 * Operators are arranged into pipelines.
93	 * They are stateful.
94	 * Each operator is an input to the next operator in the chain and an output
95	 * to the previous.
96	 */
97	export interface Operator extends Input, Output {}
98	
99	/**
100	 * Operators get access to storage that they can store their internal
101	 * state in.
102	 */
103	export interface Storage {
104	  set(key: string, value: JSONValue): void;
105	  get(key: string, def?: JSONValue): JSONValue | undefined;
106	  /**
107	   * If options is not specified, defaults to scanning all entries.
108	   */
109	  scan(options?: {prefix: string}): Stream<[string, JSONValue]>;
110	  del(key: string): void;
111	}
