17	export function constraintMatchesRow(
18	  constraint: Constraint,
19	  row: Row,
20	): boolean {
21	  for (const key in constraint) {
22	    if (!valuesEqual(row[key], constraint[key])) {
23	      return false;
24	    }
25	  }
26	  return true;
27	}
