29	/**
30	 * Constraints are compatible if:
31	 * 1. They do not have any keys in common
32	 * 2. They have keys in common, but the values for those keys are equal
33	 */
34	export function constraintsAreCompatible(
35	  left: Constraint,
36	  right: Constraint,
37	): boolean {
38	  for (const key in left) {
39	    if (key in right && !valuesEqual(left[key], right[key])) {
40	      return false;
41	    }
42	  }
43	  return true;
44	}
45	
46	export function constraintMatchesPrimaryKey(
47	  constraint: Constraint,
48	  primary: PrimaryKey,
49	): boolean {
50	  return keyMatchesPrimaryKey(Object.keys(constraint), primary);
51	}
52	
53	export function keyMatchesPrimaryKey(
54	  key: Iterable<string>,
55	  primary: PrimaryKey,
56	): boolean {
57	  const constraintKeys = [...key];
58	
59	  if (constraintKeys.length !== primary.length) {
60	    return false;
61	  }
62	
63	  // Primary key is always sorted
64	  // Constraint does not have to be sorted
65	  constraintKeys.sort(stringCompare);
66	
67	  for (let i = 0; i < constraintKeys.length; i++) {
68	    if (constraintKeys[i] !== primary[i]) {
69	      return false;
70	    }
71	  }
72	  return true;
73	}
74	
75	/**
76	 * Pulls top level `and` components out of a condition tree.
77	 * The resulting array of simple conditions would match a superset of
78	 * values that the original condition would match.
79	 *
80	 * Examples:
81	 * a AND b OR c
82	 *
83	 * In this case we cannot pull anything because the `or` is at the top level.
84	 *
85	 * a AND b AND c
86	 * We can pull all three.
87	 *
88	 * a AND (b OR c)
89	 * We can only pull `a`.
90	 */
91	export function pullSimpleAndComponents(
92	  condition: Condition,
93	): SimpleCondition[] {
94	  if (condition.type === 'and') {
95	    return condition.conditions.flatMap(pullSimpleAndComponents);
96	  }
97	
98	  if (condition.type === 'simple') {
99	    return [condition];
100	  }
101	
102	  if (condition.type === 'or' && condition.conditions.length === 1) {
103	    return pullSimpleAndComponents(condition.conditions[0]);
104	  }
105	
106	  return [];
107	}
108	
109	/**
110	 * Checks if the supplied filters constitute a primary key lookup.
111	 * If so, returns the constraint that would be used to look up the primary key.
112	 * If not, returns undefined.
113	 */
114	export function primaryKeyConstraintFromFilters(
115	  condition: Condition | undefined,
116	  primary: PrimaryKey,
117	): Constraint | undefined {
118	  if (condition === undefined) {
119	    return undefined;
120	  }
121	
122	  const conditions = pullSimpleAndComponents(condition);
123	  if (conditions.length === 0) {
124	    return undefined;
125	  }
126	
127	  const ret: Writable<Constraint> = {};
128	  for (const subCondition of conditions) {
129	    if (subCondition.op === '=') {
130	      const column = extractColumn(subCondition);
131	      if (column !== undefined) {
132	        if (!primary.includes(column.name)) {
133	          continue;
134	        }
135	        ret[column.name] = column.value;
136	      }
137	    }
138	  }
139	
140	  if (Object.keys(ret).length !== primary.length) {
141	    return undefined;
142	  }
143	
144	  return ret;
145	}
146	
147	function extractColumn(
148	  condition: SimpleCondition,
149	): {name: string; value: Value} | undefined {
150	  if (condition.left.type === 'column') {
151	    assert(
152	      condition.right.type === 'literal',
153	      () =>
154	        `extractColumn: expected right side to be literal, got ${condition.right.type}`,
155	    );
156	    return {name: condition.left.name, value: condition.right.value};
157	  }
158	
159	  return undefined;
160	}
161	
162	export class SetOfConstraint {
163	  #data: Constraint[] = [];
164	
165	  constructor() {
166	    assertTesting('SetOfConstraint is only available in testing');
167	  }
168	
169	  #indexOf(value: Constraint): number {
170	    return this.#data.findIndex(v => constraintEquals(v, value));
171	  }
172	
173	  has(value: Constraint): boolean {
174	    return this.#indexOf(value) !== -1;
175	  }
176	
177	  add(value: Constraint): this {
178	    if (!this.has(value)) {
179	      this.#data.push(value);
180	    }
181	    return this;
182	  }
183	}
184	
185	function constraintEquals(a: Constraint, b: Constraint): boolean {
186	  const aEntries = Object.entries(a);
187	  const bEntries = Object.entries(b);
188	  if (aEntries.length !== bEntries.length) {
189	    return false;
190	  }
191	  for (let i = 0; i < aEntries.length; i++) {
192	    if (
193	      aEntries[i][0] !== bEntries[i][0] ||
194	      !valuesEqual(aEntries[i][1], bEntries[i][1])
195	    ) {
196	      return false;
197	    }
198	  }
199	  return true;
200	}
